    solution: `ส่วนแบ่งกำไรรวมของหุ้นส่วน ก = 165,000`,
    theory: `เมื่อสัญญาหุ้นส่วนกำหนดวิธีแบ่งกำไรที่ซับซ้อนกว่าสัดส่วนเดียว (เช่น ให้ผลตอบแทนหุ้นส่วนที่ทำงานหรือลงทุนมากกว่า) จะใช้ลำดับการจัดสรร 3 ขั้นตอนตามลำดับก่อนหลัง:<br/><br/>
    1. <strong>เงินเดือน (Salary Allowance)</strong> — ตอบแทนหุ้นส่วนที่บริหารงานจริง<br/>
    2. <strong>ดอกเบี้ยทุน (Interest on Capital)</strong> — ตอบแทนตามสัดส่วนเงินลงทุน<br/>
    3. <strong>ส่วนที่เหลือ (Remainder)</strong> — แบ่งตามอัตราส่วนที่ตกลงกัน (มักเป็นสัดส่วนเดียวกับที่ตกลงแบ่งกำไรขาดทุน)<br/><br/>
    ข้อสำคัญ: หากกำไรสุทธิไม่พอสำหรับเงินเดือน+ดอกเบี้ยทุน ส่วนที่เหลือจะติดลบ และต้องหักออกจากหุ้นส่วนตามสัดส่วนเช่นเดิม (ไม่ใช่ปรับลดเงินเดือน/ดอกเบี้ยทุนลง)`,
    example: `กำไรสุทธิ 100,000 | เงินเดือน ก 30,000 | ดอกเบี้ยทุน รวม 10,000 | ส่วนที่เหลือแบ่ง 50:50
ส่วนที่เหลือ = 100,000 - 30,000 - 10,000 = 60,000 → คนละ 30,000
ก ได้รับ = 30,000 (เงินเดือน) + 30,000 (ส่วนที่เหลือ) = 60,000`,
