    example: `หุ้นส่วน A, B, C แบ่งกำไรขาดทุน 1:1:1 ทุนคนละ 100,000 บาท C ลาออก ห้างจ่ายคืนทุน 130,000 บาท\nโบนัสให้ C = 30,000 บาท หักจาก A และ B คนละเท่าๆ กัน (คนละ 15,000 บาท) ทุน A และ B ลดลงคนละ 15,000 บาท`,
    task: `ห้างหุ้นส่วน ก, ข, และ ค มีทุนคงเหลือ ณ วันสิ้นงวด 200,000 บาท, 150,000 บาท และ 100,000 บาท ตามลำดับ แบ่งกำไรขาดทุนในสัดส่วน 5:3:2 ต่อมาหุ้นส่วน ค ลาออก และห้างตกลงจ่ายเงินคืนทุนให้ ค ทั้งสิ้น <strong>120,000 บาท</strong> โดยใช้วิธีโบนัส (Bonus Method)<br/><br/>จงคำนวณจำนวนทุนที่ลดลงของหุ้นส่วน ก จากการลาออกของ ค แล้วพิมพ์คำตอบในรูปแบบ:<br/><code>ทุนที่ลดลงของ ก = [ตัวเลข]</code>`
