    solution: `ส่วนเกินทุนหุ้นทุนซื้อคืน = 4,200`,
    theory: `<strong>หุ้นทุนซื้อคืน (Treasury Stock)</strong> คือหุ้นสามัญ/หุ้นบุริมสิทธิที่บริษัทออกจำหน่ายแล้วซื้อกลับคืนมาเป็นของบริษัทเอง โดยยังไม่ยกเลิก (ต่างจากการลดทุนที่ยกเลิกหุ้นถาวร) หุ้นทุนซื้อคืนไม่มีสิทธิออกเสียงและไม่ได้รับเงินปันผล และถือเป็น<strong>รายการหักจากส่วนของผู้ถือหุ้น</strong> (Contra-Equity) ไม่ใช่สินทรัพย์<br/><br/>
    <strong>วิธีบันทึกบัญชีที่นิยม: วิธีราคาทุน (Cost Method)</strong><br/>
    1. <strong>ซื้อคืน:</strong> Dr. หุ้นทุนซื้อคืน (ราคาทุนที่ซื้อ) / Cr. เงินสด — ไม่สนใจมูลค่าที่ตราไว้ (Par) เลย<br/>
    2. <strong>ขายคืน (Reissue) สูงกว่าราคาทุน:</strong> Dr. เงินสด (ราคาขาย) / Cr. หุ้นทุนซื้อคืน (ราคาทุน) / Cr. <strong>ส่วนเกินทุนหุ้นทุนซื้อคืน (APIC — Treasury Stock)</strong> (ผลต่าง) — ส่วนต่างนี้<strong>ไม่ใช่กำไร</strong> จึงไม่ผ่านงบกำไรขาดทุน แต่บันทึกตรงเข้าส่วนของผู้ถือหุ้น<br/>
    3. <strong>ขายคืนต่ำกว่าราคาทุน:</strong> ผลต่างหักจาก "ส่วนเกินทุนหุ้นทุนซื้อคืน" ที่มีอยู่ก่อนหน้าให้หมดก่อน ส่วนที่เกินจึงหักจาก "กำไรสะสม"<br/><br/>
    ผลกระทบต่อส่วนของผู้ถือหุ้น: การซื้อหุ้นคืนทำให้<strong>ส่วนของผู้ถือหุ้นรวมลดลง</strong>ทันทีเท่าราคาทุนที่ซื้อ (เพราะจ่ายเงินสดออกแต่จำนวนหุ้นในตลาดลดลง) และเมื่อขายคืนได้ ส่วนของผู้ถือหุ้นจะเพิ่มขึ้นกลับมาตามราคาขาย`,
    example: `ซื้อหุ้นทุนซื้อคืน 200 หุ้น ราคาหุ้นละ 15 บาท (ต้นทุนรวม 3,000) ต่อมาขายคืน 100 หุ้น ราคาหุ้นละ 12 บาท (ต่ำกว่าทุน)
เงินสดรับ = 1,200 | ต้นทุนหุ้นที่ขาย = 100×15=1,500 | ส่วนต่างขาดทุน 300 หักจากส่วนเกินทุนหุ้นทุนซื้อคืนที่มีอยู่ก่อน (ถ้าไม่พอจึงหักกำไรสะสม)`,
    task: `บริษัทจำกัดซื้อหุ้นสามัญของตนเองคืนจำนวน <strong>1,000 หุ้น</strong> ในราคาหุ้นละ <strong>25 บาท</strong> (บันทึกด้วยวิธีราคาทุน) ต่อมาบริษัทนำหุ้นทุนซื้อคืนออกขายคืนสู่ตลาดจำนวน <strong>600 หุ้น</strong> ในราคาหุ้นละ <strong>32 บาท</strong><br/><br/>
    จงคำนวณจำนวนเงินที่ต้องบันทึกเป็น "ส่วนเกินทุนหุ้นทุนซื้อคืน" จากการขายคืนครั้งนี้ แล้วพิมพ์คำตอบในรูปแบบ:<br/>
    <code>ส่วนเกินทุนหุ้นทุนซื้อคืน = [ตัวเลข]</code>`
