      const val = parseNumberAfterEquals(code);
      if (val === null) {
        throw new Error("ไม่พบคำตอบในรูปแบบ 'ส่วนเกินทุนจากการตีราคาที่รับรู้ใน OCI ปีที่ 2 = ตัวเลข'");
      }
      log(`✓ อ่านค่าคำตอบได้: ${val.toLocaleString()}`);
